let windowSize = 30m;

// S17: C2 Hijack (Unsigned MAVLink) — UAVMavsec_CL엔 SignatureValid 없음, UnsignedCount/FailedCount 사용
let S17 =
    UAVMavsec_CL
    | where TimeGenerated > ago(windowSize)
    | where UnsignedCount > 0 or FailedCount > 0
    | extend Stage = 'S17', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S115: Control Channel Takeover — 제안 스키마 전용 테이블 없음, UAVMissionEvent_CL 모드전환으로 대리 탐지
let S115 =
    UAVMissionEvent_CL
    | where TimeGenerated > ago(windowSize)
    | where CustomModeBefore != CustomModeAfter
    | extend Stage = 'S115', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S116: Attitude Data Corruption — UAVTelemetry_CL, 비정상 자세/컴퍼스 분산값
let S116 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where CompassVariance > 5 or abs(Roll_rad) > 3.2 or abs(Pitch_rad) > 3.2
    | extend Stage = 'S116', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S123: Induced Fixed-Wing Stall — UAVTelemetry_CL, 저속 대기속도
let S123 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where Airspeed_ms >= 0 and Airspeed_ms < 8
    | extend Stage = 'S123', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

union S17, S115, S116, S123
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by UAVId
| where StageCount >= 3
| extend CampaignType = "C31_제어강탈_C2하이재킹_제어권전환_자세오염_고정익실속"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, UAVId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
